<?php
require_once __DIR__.'/../config.php';require_once __DIR__.'/lib/Portal.php';require_once __DIR__.'/lib/Layout.php';$ctx=rxp_context($pdo);$owner=rxp_target_reseller($ctx);$flash='';$ft='ok';if(($_SERVER['REQUEST_METHOD']??'')==='POST'){$act=(string)($_POST['action']??'');try{if($act==='add'){$num=preg_replace('/\D/','',(string)($_POST['cardnumber']??''));$name=mb_substr(trim((string)($_POST['namecard']??'')),0,100);if(!in_array(strlen($num),[16,19],true)||$name==='')throw new DomainException('شماره کارت یا نام نامعتبر است.');$pdo->prepare('INSERT INTO reseller_cards(reseller_id,cardnumber,namecard) VALUES(?,?,?)')->execute([$owner,$num,$name]);rxp_audit($pdo,$ctx,'card.add',$owner);$flash='کارت اضافه شد.';}elseif($act==='del'){$pdo->prepare('DELETE FROM reseller_cards WHERE id=? AND reseller_id=?')->execute([(int)($_POST['id']??0),$owner]);rxp_audit($pdo,$ctx,'card.delete',$owner);$flash='کارت حذف شد.';}}catch(Throwable $e){$flash=rxp_public_exception_message($e, basename(__FILE__));$ft='err';}}$q=$pdo->prepare('SELECT * FROM reseller_cards WHERE reseller_id=? ORDER BY id');$q->execute([$owner]);$cards=$q->fetchAll(PDO::FETCH_ASSOC);rxp_layout_start($ctx,'کارت‌های بانکی','cards.php');rxp_flash($flash,$ft);?>
<h1 class="rxp-title">کارت‌های بانکی</h1><?php if($ctx['role']==='super'):?><div class="rxp-card"><form method="get"><select name="owner" onchange="this.form.submit()"><?php foreach($ctx['scope_ids'] as $id):?><option value="<?=$id?>" <?=$owner===$id?'selected':''?>>نماینده #<?=$id?></option><?php endforeach;?></select></form></div><?php endif;?><div class="rxp-card"><h2>افزودن کارت</h2><form method="post" class="rxp-form"><input type="hidden" name="owner" value="<?=rxp_h($owner)?>"><input type="hidden" name="action" value="add"><div class="rxp-field"><label>شماره کارت</label><input name="cardnumber" inputmode="numeric" required></div><div class="rxp-field"><label>نام صاحب کارت</label><input name="namecard" required></div><button class="rxp-btn green">افزودن</button></form></div><div class="rxp-card"><table class="rxp-table"><tr><th>شماره</th><th>نام</th><th></th></tr><?php foreach($cards as $c):?><tr><td style="direction:ltr"><code><?=rxp_h($c['cardnumber'])?></code></td><td><?=rxp_h($c['namecard'])?></td><td><form method="post"><input type="hidden" name="owner" value="<?=rxp_h($owner)?>"><input type="hidden" name="action" value="del"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><button class="rxp-btn red">حذف</button></form></td></tr><?php endforeach;?></table></div><?php rxp_layout_end();
